import { Cart, Category, ContactPointAddress, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper enters a billing address.
*/
export type CheckoutBillingAddress = {
    events: Array<Cart | ContactPointAddress | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutBillingAddressBuilder {

    private checkoutBillingAddress: CheckoutBillingAddress = {
        events: []
    }

    private cart!: Cart;
    private contactPointAddress!: ContactPointAddress;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutBillingAddressBuilder {
        this.cart = cart;
        return this;
    }
    public withContactPointAddress(contactPointAddress: ContactPointAddress) : CheckoutBillingAddressBuilder {
        this.contactPointAddress = contactPointAddress;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutBillingAddressBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutBillingAddressBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutBillingAddressBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutBillingAddress {
        if(this.cart) {
            this.checkoutBillingAddress.events.push(this.cart);
        }
        if(this.contactPointAddress) {
            this.checkoutBillingAddress.events.push(this.contactPointAddress);
        }
        if(this.errorEvent) {
            this.checkoutBillingAddress.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutBillingAddress.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutBillingAddress.events.push(this.partyIdentification);
        }

        return this.checkoutBillingAddress;
    }
}
